descriptor.templateCss:
.tb-rpc-text-editor {
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    padding: 10px;
    gap: 8px;
}

.tb-rpc-text-editor .title-container {
    flex: 0 0 auto;
    font-weight: 500;
    text-align: center;
}

.tb-rpc-text-editor .title-container.hidden {
    display: none;
}

.tb-rpc-text-editor .editor-container {
    flex: 1 1 auto;
    min-height: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.tb-rpc-text-editor .value-textarea {
    flex: 1 1 auto;
    width: 100%;
    min-height: 80px;
    resize: none;
    box-sizing: border-box;
    padding: 8px;
    border: 1px solid rgba(0, 0, 0, 0.25);
    border-radius: 4px;
    font-family: monospace;
    font-size: 14px;
    outline: none;
}

.tb-rpc-text-editor .value-textarea:focus {
    border-color: #1976d2;
}

.tb-rpc-text-editor .save-button {
    flex: 0 0 auto;
    width: 100%;
    margin: 0;
}

.tb-rpc-text-editor .status-container {
    flex: 0 0 auto;
    min-height: 18px;
    text-align: center;
}

.tb-rpc-text-editor .status {
    font-size: 12px;
    color: rgba(0, 0, 0, 0.6);
}

.tb-rpc-text-editor .status.error {
    color: #d32f2f;
}

descriptor.controllerScript:
var requestTimeout = 5000;

self.onInit = function() {
    self.ctx.ngZone.run(function() {
        init();
        self.ctx.detectChanges();
        loadValue();
    });
};

function init() {
    var settings = self.ctx.settings || {};
    var subscription = self.ctx.defaultSubscription;

    self.ctx.$scope.rpcEnabled = !!(subscription && subscription.rpcEnabled);
    self.ctx.$scope.title = settings.title || '';
    self.ctx.$scope.showTitle = !!self.ctx.$scope.title;
    self.ctx.$scope.buttonText = settings.buttonText || 'Save';
    self.ctx.$scope.textValue = '';
    self.ctx.$scope.loading = false;
    self.ctx.$scope.saving = false;
    self.ctx.$scope.status = '';
    self.ctx.$scope.isError = false;

    requestTimeout = settings.requestTimeout || 5000;

    if (!self.ctx.$scope.rpcEnabled) {
        setStatus('Target device is not set!', true);
    }

    self.ctx.$scope.save = function() {
        saveValue();
    };
}

function loadValue() {
    if (!self.ctx.$scope.rpcEnabled) {
        return;
    }

    var settings = self.ctx.settings || {};
    var getterMethod = settings.getterMethodName || 'getValue';

    self.ctx.$scope.loading = true;
    setStatus('Loading...', false);
    self.ctx.detectChanges();

    self.ctx.controlApi.sendTwoWayCommand(
        getterMethod,
        {},
        requestTimeout
    ).subscribe(
        function(response) {
            self.ctx.$scope.loading = false;
            self.ctx.$scope.textValue = responseToText(response);
            setStatus('', false);
            self.ctx.controlApi.completedCommand();
            self.ctx.detectChanges();
        },
        function(error) {
            self.ctx.$scope.loading = false;
            setStatus(formatError(error), true);
            self.ctx.detectChanges();
        }
    );
}

function saveValue() {
    if (!self.ctx.$scope.rpcEnabled) {
        return;
    }

    var settings = self.ctx.settings || {};
    var setterMethod = settings.setterMethodName || 'setValue';
    var value = self.ctx.$scope.textValue;

    self.ctx.$scope.saving = true;
    setStatus('Saving...', false);
    self.ctx.detectChanges();

    self.ctx.controlApi.sendTwoWayCommand(
        setterMethod,
        value,
        requestTimeout
    ).subscribe(
        function() {
            self.ctx.$scope.saving = false;
            setStatus('Saved', false);
            self.ctx.controlApi.completedCommand();
            self.ctx.detectChanges();
        },
        function(error) {
            self.ctx.$scope.saving = false;
            setStatus(formatError(error), true);
            self.ctx.detectChanges();
        }
    );
}

function responseToText(response) {
    if (response === null || typeof response === 'undefined') {
        return '';
    }

    if (typeof response === 'string') {
        return response;
    }

    if (typeof response === 'object' &&
        Object.prototype.hasOwnProperty.call(response, 'value')) {
        var value = response.value;
        if (value === null || typeof value === 'undefined') {
            return '';
        }
        if (typeof value === 'string') {
            return value;
        }
        if (typeof value === 'object') {
            try {
                return JSON.stringify(value, null, 2);
            } catch (e) {
                return String(value);
            }
        }
        return String(value);
    }

    if (typeof response === 'object') {
        try {
            return JSON.stringify(response, null, 2);
        } catch (e) {
            return String(response);
        }
    }

    return String(response);
}

function formatError(error) {
    if (!error) {
        return 'RPC error';
    }

    if (error.error && error.error.message) {
        return error.error.message;
    }

    if (error.status || error.statusText) {
        return (error.status || '') + (error.statusText ? ': ' + error.statusText : '');
    }

    if (error.message) {
        return error.message;
    }

    return 'RPC error';
}

function setStatus(message, isError) {
    self.ctx.$scope.status = message || '';
    self.ctx.$scope.isError = !!isError;
}

self.onDestroy = function() {
    self.ctx.controlApi.completedCommand();
};

self.typeParameters = function() {
    return {
        singleEntity: true,
        dataKeysOptional: true
    };
};
